import{H as e,V as t,et as n,j as r}from"./chunks/framework.CW0zsFMp.js";import{Go as i}from"./chunks/assets.BxHYjuf8.js";var a=JSON.parse(`{"title":"锁","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/locks.md","filePath":"mysql/locks.md"}`),o={name:`mysql/locks.md`};function s(r,a,o,s,c,l){return n(),t(`div`,null,[...a[0]||=[e(`<h1 id="锁" tabindex="-1">锁 <a class="header-anchor" href="#锁" aria-label="Permalink to “锁”">​</a></h1><p>锁是计算机协调多个进程或线程并发访问某一资源的机制。在数据库中，除传统的计算资源(CPU、RAM、I/O)的争用以外，数据也是一种供许多用户共享的资源。如何保证数据并发访问的一致性、有效性是所有数据库必须解决的一个问题，锁冲突也是影响数据库并发访问性能的一个重要因素。从这个角度来说，锁对数据库而言显得尤其重要，也更加复杂</p><p>MySQL中的锁，按照锁的粒度分，分为以下三类：</p><ol><li><p>全局锁：锁定数据库中的所有表</p></li><li><p>表级锁：每次操作锁住整张表</p></li><li><p>行级锁：每次操作锁住对应的行数据</p></li></ol><h2 id="_1-全局锁" tabindex="-1">1.全局锁 <a class="header-anchor" href="#_1-全局锁" aria-label="Permalink to “1.全局锁”">​</a></h2><p>全局锁就是对整个数据库实例加锁，加锁后整个实例就处于<strong>只读状态</strong>，后续的DML的写语句，DDL语句，已经更新操作的事务提交语句都将<strong>被阻塞</strong>。</p><p>其典型的使用场景是做全库的逻辑备份，对所有的表进行锁定，从而获取一致性视图，保证数据的完整性。</p><h3 id="_1-1-语句" tabindex="-1">1.1 语句 <a class="header-anchor" href="#_1-1-语句" aria-label="Permalink to “1.1 语句”">​</a></h3><p>使用全局锁</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flush tables </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">with</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lock;</span></span></code></pre></div><p>拷贝数据库</p><div class="language-PowerShell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">PowerShell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mysqldump [</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">--single-transaction</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uroot </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] itcast </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> itcast.sql</span></span></code></pre></div><ul><li><p>不属于MySQL命令，需要退出数据库管理系统后在命令行执行</p></li><li><p>只适用于支持 可重复读隔离级别的事务 的存储引擎</p></li><li><p>-u后面跟用户名，如root用户，但要保证用户有足够权限拷贝数据库</p></li><li><p>-p后面可以跟用户密码，也可以不跟，不跟命令执行后需要手动输入密码，建议不加密码</p></li><li><p>itcast代表要拷贝的数据库，只写数据库名就可以了</p></li><li><p>itcast.sql可以写绝对路径，但要保证路径存在，格式是<code>D:/backup/itcast.sql</code>或<code>D:\\\\backup\\\\itcast.sql</code></p></li></ul><p>释放全局锁</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">unlock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tables;</span></span></code></pre></div><h3 id="_1-2-特点" tabindex="-1">1.2 特点 <a class="header-anchor" href="#_1-2-特点" aria-label="Permalink to “1.2 特点”">​</a></h3><p>数据库中加全局锁，是一个比较重的操作，存在以下问题:</p><ol><li><p>如果在主库上备份，那么在备份期间都不能执行更新，业务基本上就得停摆</p></li><li><p>如果在从库上备份，那么在备份期间从库不能执行主库同步过来的二进制日志(binlog)，会导致主从延迟（该结构会在后续主从复制讲解）</p></li></ol><p><strong>解决方法</strong>：</p><p>在InnoDB引擎中，我们可以在备份时加上参数 <code>--single-transaction</code> 参数来完成不加锁的一致性数据备份，通过加上这个参数，确保了在备份开始时创建一个一致性的快照，通过启动一个新的事务来实现这一点（该事务的隔离级别是Repeatable Read级别），从而确保在备份数据库时可以对数据库数据进行操作。</p><h2 id="_2-表级锁" tabindex="-1">2.表级锁 <a class="header-anchor" href="#_2-表级锁" aria-label="Permalink to “2.表级锁”">​</a></h2><p>每次操作<strong>锁住整张表</strong>。锁定粒度大，发生锁的冲突的概率最高，并发度最低。应用在MyISAM、InnoDB、BDB等存储引擎中</p><p>对于表级锁，主要分为以下三类：</p><ol><li><p>表锁</p></li><li><p>元数据锁（meta data lock，MDL）</p></li><li><p>意向锁</p></li></ol><h3 id="_2-1-表锁" tabindex="-1">2.1 表锁 <a class="header-anchor" href="#_2-1-表锁" aria-label="Permalink to “2.1 表锁”">​</a></h3><p>对于表锁，分为两类：</p><ol><li><p>表共享读锁（read lock）：当前客户端和其他客户端都能读，当前客户端不能写，其他客户端写被阻塞</p></li><li><p>表独占写锁（write lock）：当前客户端可以读和写，其他客户端的读和写会被阻塞</p></li></ol><p>加锁</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lock tables 表名... </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|write;</span></span></code></pre></div><p>释放锁</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">unlock</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tables;</span></span></code></pre></div><ul><li>用户端断开与数据库的连接会自动释放锁，如事务结束事务内加的锁全部释放</li></ul><h3 id="_2-2-元数据锁-mdl" tabindex="-1">2.2 元数据锁（MDL） <a class="header-anchor" href="#_2-2-元数据锁-mdl" aria-label="Permalink to “2.2 元数据锁（MDL）”">​</a></h3><p>MDL加锁过程是系统自动控制，无需显式使用，在访问一张表的时候会自动加上。MDL锁主要作用是维护表元数据的数据一致性，在表上有活动事务的时候，不可以对元数据进行写入操作。</p><ul><li>元数据：描述数据库对象结构的信息，而不是实际的数据内容，是描述数据库对象的结构和属性的信息，如表结构、视图定义等</li></ul><p>元数据锁是为了避免DML与DDL冲突，保证读写的正确性。</p><p>在MySQL5.5中引入了MDL，当对一张表进行增删改查时，加<strong>MDL读锁（共享）</strong>；当对表结构进行变更时，加<strong>MDL写锁（排他）</strong></p><table tabindex="0"><thead><tr><th>对应SQL</th><th>锁类型</th><th>说明</th></tr></thead><tbody><tr><td>lock tables xxx read | write</td><td>SHARED_READ_ONLY|SHARED_NO_READ_WRITE</td><td></td></tr><tr><td>select 、 select … lock in share mode</td><td>SHARED_READ（共享读锁）</td><td>与SHARED_READ、SHARED_WRITE兼容，与EXCLUSIVE互斥</td></tr><tr><td>insert 、update、delete、select …for update</td><td>SHARED_WRITE（共享写锁）</td><td>与SHARED_READ、SHARED_WRITE兼容，与EXCLUSIVE互斥</td></tr><tr><td>alter table …</td><td>EXCLUSIVE（写锁）</td><td>与其他的MDL都互斥</td></tr></tbody></table><ul><li>SHARED_READ和SHARED_WRITE是兼容的，即可以同时存在，但是这两个锁和EXCLYSIVE是互斥的，即EXCLYSIVE和他们不能同时存在，会发生阻塞</li></ul><p>查看元数据锁</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> object_type,object_schema,object_name,lock_type,lock_duration </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> performance_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">metadata_locks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h3 id="_2-3-意向锁" tabindex="-1">2.3 意向锁 <a class="header-anchor" href="#_2-3-意向锁" aria-label="Permalink to “2.3 意向锁”">​</a></h3><p>当线程A对基本表某一行加行锁后，如果线程B要对基本表加表锁，那么MySQL会检查基本表的每一行，判断是否有其他线程加的锁，如果有，会判断表锁和行锁是否冲突，如果不冲突会直接加锁，如果冲突会被阻塞，直到其他线程全部释放锁</p><p>为了避免DML在执行时，加的行锁与表锁的冲突，在InnoDB中引入了意向锁，使得表锁不用检查每行数据是否加锁，使用意向锁来减少表锁的检查</p><p>意向锁分为两类：</p><ul><li><p><strong>意向共享锁（IS）</strong>：与表锁共享锁（read）兼容，与表锁排他锁（write）互斥</p></li><li><p><strong>意向排他锁（IX）</strong>：与表锁共享锁（read）和排他锁（write）都互斥，意向锁之间不会互斥</p></li></ul><p>意向锁的好处：</p><ol><li><p>如果没有「意向锁」，那么加「独占表锁」时，就需要遍历表里所有记录，查看是否有记录存在独占锁，这样效率会很慢</p></li><li><p>那么有了「意向锁」，由于在对记录加独占锁前，先会加上表级别的意向独占锁，那么在加「独占表锁」时，直接查该表是否有意向独占锁，如果有就意味着表里已经有记录被加了独占锁，这样就不用去遍历表里的记录</p></li></ol><blockquote><p>意向锁的目的是为了快速判断表里是否有记录被加锁</p></blockquote><p>查看锁及元数据锁的加锁情况</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> object_schema,object_name,index_name,lock_type,lock_mode,lock_data </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> performance_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">data_locks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>添加意向共享锁</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ... lock </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> share mode;</span></span></code></pre></div><ul><li>执行语句后，MySQL会先在表上加上意向共享锁，然后对读取的记录加共享锁，也就是说会加两个锁</li></ul><p>添加意向独占锁</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">insert</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">、 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">、 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">、 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ... </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> update</span></span></code></pre></div><ul><li><p>在执行增删改语句后会自动加上意向独占锁，不需要手动指定</p></li><li><p>执行语句后，MySQL会先在表上加上意向独占锁，然后对读取的记录加独占锁，也就是说会加两个锁</p></li></ul><h3 id="_2-4-auto-inc锁" tabindex="-1">2.4 AUTO-INC锁 <a class="header-anchor" href="#_2-4-auto-inc锁" aria-label="Permalink to “2.4 AUTO-INC锁”">​</a></h3><p><img src="`+i+`" alt="7422290ad1684e6abfe7a2b4feb41acapng" width="961" height="971"></p><h2 id="_3-行级锁" tabindex="-1">3.行级锁 <a class="header-anchor" href="#_3-行级锁" aria-label="Permalink to “3.行级锁”">​</a></h2><p>行级锁，每次操作<strong>锁住对应的行数据</strong>。锁定粒度最小，发生锁冲突的概率最低，并发度最高。应用在InnoDB存储引擎中</p><p>InnoDB数据是基于索引组成的，行锁是通过对索引上的索引项加锁来实现的，而不是对记录加的锁</p><p>行级锁主要分为三类：</p><ol><li><p>行锁(Record Lock)：锁定单个行记录的锁，防止其他事务对此行进行update和delete。在RC、RR隔离级别下都支持</p></li><li><p>间隙锁(GapLock)：锁定索引记录间隙(不含该记录)，确保索引记录间隙不变，防止其他事务在这个间隙进行insert，产生幻读。在RR隔离级别下都支持</p></li><li><p>临键锁(Next-Key Lock)：行锁和间隙锁组合，同时锁住数据，并锁住数据前面的间隙Gap。在RR隔离级别下支持</p></li></ol><h3 id="_3-1-record-lock-行锁" tabindex="-1">3.1 Record Lock（行锁） <a class="header-anchor" href="#_3-1-record-lock-行锁" aria-label="Permalink to “3.1 Record Lock（行锁）”">​</a></h3><p>Record Lock 称为记录锁，锁住的是一行记录。而且记录锁是有 S 锁和 X 锁之分：</p><ol><li><p>共享锁(S)：允许一个事务去读一行，阻止其他事务获得相同数据集的排它锁。</p><ul><li>当前客户端和其他客户端都能读，当前客户端不能写，其他客户端写被阻塞</li></ul></li><li><p>排他锁(X)：允许获取排他锁的事务更新数据，阻止其他事务获得相同数据集的共享锁和排他锁。</p><ul><li>当前客户端可以读和写，其他客户端的读和写会被阻塞</li></ul></li></ol><table tabindex="0"><thead><tr><th></th><th>S(共享锁)</th><th>X(排他锁)</th></tr></thead><tbody><tr><td>S(共享锁)</td><td>兼容</td><td>冲突</td></tr><tr><td>X(排他锁)</td><td>冲突</td><td>冲突</td></tr></tbody></table><p>行锁类型：</p><table tabindex="0"><thead><tr><th>SQL</th><th>行锁类型</th><th>说明</th></tr></thead><tbody><tr><td>insert...，update...，delete …</td><td>排他锁</td><td>自动加锁</td></tr><tr><td>select...（正常）</td><td>不加任何锁</td><td></td></tr><tr><td>select … lock in share mode</td><td>共享锁</td><td>需要手动select之后加上lock in share mode</td></tr><tr><td>select … for update</td><td>排他锁</td><td>需要手动在select之后for update</td></tr></tbody></table><p>默认情况下，InnoDB在 REPEATABLE READ事务隔离级别运行，InnoDB使用 next-key锁进行搜索和索引扫描，以防止幻读。</p><ol><li><p>通过唯一索引进行检索时，对已存在的记录进行等值匹配时，将会<strong>自动优化为行锁</strong></p></li><li><p>InnoDB的行锁是针对于索引加的锁，如果不通过索引检索数据，那么InnoDB将对表中的所有记录加锁，此时<strong>就会升级为表锁</strong></p></li></ol><p>查看意向锁及行锁的加锁情况</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> object_schema,object_name,index_name,lock_type,lock_mode,lock_data </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> performance_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">data_locks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h3 id="_3-2-gap-lock-间隙锁-和next-key-lock-临键锁" tabindex="-1">3.2 Gap Lock（间隙锁）和Next-Key Lock（临键锁） <a class="header-anchor" href="#_3-2-gap-lock-间隙锁-和next-key-lock-临键锁" aria-label="Permalink to “3.2 Gap Lock（间隙锁）和Next-Key Lock（临键锁）”">​</a></h3><p>默认情况下，InnoDB在 REPEATABLE READ（可重复读）事务隔离级别运行，InnoDB使用 next-key 锁进行搜索和索引扫描，以防止幻读</p><ol><li><p>索引上的等值查询(唯一索引)：给不存在的记录加锁时, <strong>优化为间隙锁</strong></p><ul><li>会在应存在的位置（间隙）插入一个间隙锁，其他事务访问这个间隙时会被阻塞</li></ul></li><li><p>索引上的等值查询(非唯一性索引)：向右遍历时最后一个值不满足查询需求时，next-key lock <strong>退化为间隙锁</strong></p><ul><li><p>如果值存在，会把查询的节点加行锁，并且在查询的节点前后两个间隙都添加间隙锁</p></li><li><p>如果值不存在，会在应存在的位置（间隙）插入一个间隙锁</p></li></ul></li><li><p>索引上的范围查询(唯一索引)：会访问到不满足条件的第一个值为止</p><ul><li>对查询范围内的所有行加行锁，对查询范围内的所有间隙加间隙锁</li></ul></li><li><p>索引上的范围查询(非唯一索引)：向左遍历时第一个范围不满足查询范围，向右遍历时最后一个范围不满足查询范围</p><ul><li>对查询范围内的所有行加行锁，对查询范围内的所有间隙以及起始点的前一个间隙和终止点的后一个间隙加间隙锁</li></ul></li></ol>`,77)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};